import{_ as e,o as n,c as t,a2 as s}from"./chunks/framework.DtFGJNng.js";const k=JSON.parse('{"title":"Konsep singkat","description":"","frontmatter":{},"headers":[],"relativePath":"konsep-singkat.md","filePath":"konsep-singkat.md","lastUpdated":1794463556000}'),i={name:"konsep-singkat.md"};function d(r,a,o,p,l,u){return n(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="konsep-singkat" tabindex="-1">Konsep singkat <a class="header-anchor" href="#konsep-singkat" aria-label="Permalink to &quot;Konsep singkat&quot;">​</a></h1><p>Seluruh model deuz dalam satu halaman. Penjelasan yang lebih panjang ada di <a href="./alur-berpikir">Alur berpikir</a> dan <a href="./alur-kerja">Alur kerja</a>.</p><h2 id="dua-tempat-yang-sudah-dibangun-dan-yang-sedang-dikerjakan" tabindex="-1">Dua tempat: yang sudah dibangun dan yang sedang dikerjakan <a class="header-anchor" href="#dua-tempat-yang-sudah-dibangun-dan-yang-sedang-dikerjakan" aria-label="Permalink to &quot;Dua tempat: yang sudah dibangun dan yang sedang dikerjakan&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>deuz/</span></span>
<span class="line"><span>├── specs/                      ← HOMES: sistem sebagaimana SUDAH dibangun</span></span>
<span class="line"><span>│   └── pemesanan-buku/spec.md</span></span>
<span class="line"><span>└── work/                       ← pekerjaan yang SEDANG berjalan</span></span>
<span class="line"><span>    ├── pemesanan-buku/</span></span>
<span class="line"><span>    └── archive/                ← work yang sudah selesai, disimpan untuk rujukan</span></span></code></pre></div><ul><li><strong>Homes</strong> adalah sumber kebenaran permanen: spec perilaku (<code>deuz/specs/</code>), file desain, dan definisi API. Sebuah home <strong>hanya berisi yang sudah dibangun</strong>. Rencana tidak pernah ditulis langsung ke sana.</li><li><strong>Work</strong> adalah satu folder per fitur atau perubahan. Semua dokumen perencanaannya ada di sini sampai pekerjaannya selesai.</li></ul><p>Sistem yang benar-benar baru tetap dimulai dari <code>specs/</code> yang kosong. Spec lahir lewat work pertama, lalu masuk ke home saat work itu di-archive.</p><h2 id="artifact-dan-urutannya" tabindex="-1">Artifact dan urutannya <a class="header-anchor" href="#artifact-dan-urutannya" aria-label="Permalink to &quot;Artifact dan urutannya&quot;">​</a></h2><p>Setiap work berisi dokumen (artifact) dengan urutan tetap:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proposal          (analyst; + business bila ada dampak bisnis)</span></span>
<span class="line"><span>  └─ specs        (analyst; + business bila ada aturan yang perlu disetujui)</span></span>
<span class="line"><span>       └─ ui-design      (designer)</span></span>
<span class="line"><span>            └─ api-contract   (backend + frontend)</span></span>
<span class="line"><span>                 ├─ tasks-backend   (backend)</span></span>
<span class="line"><span>                 ├─ tasks-frontend  (frontend)</span></span>
<span class="line"><span>                 └─ tasks-test      (qa)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Artifact</th><th>Menjawab</th></tr></thead><tbody><tr><td><code>proposal</code></td><td>Kenapa dikerjakan, apa yang berubah, siapa yang terdampak, dan apakah bisnis setuju</td></tr><tr><td><code>specs</code></td><td>Apa yang harus dilakukan sistem, dalam bahasa bisnis (requirement dan scenario)</td></tr><tr><td><code>ui-design</code></td><td>Seperti apa tampilannya</td></tr><tr><td><code>api-contract</code></td><td>Bentuk API yang disepakati backend dan frontend</td></tr><tr><td><code>tasks-*</code></td><td>Bagaimana mengerjakannya, per peran, dengan cara verifikasi tiap task</td></tr></tbody></table><p>Sebuah artifact bisa dimulai kalau semua artifact yang dibutuhkannya sudah <code>ready</code> atau <code>skipped</code>.</p><h2 id="peran-dan-konfirmasi" tabindex="-1">Peran dan konfirmasi <a class="header-anchor" href="#peran-dan-konfirmasi" aria-label="Permalink to &quot;Peran dan konfirmasi&quot;">​</a></h2><p>Setiap artifact punya <strong>pemilik</strong> berupa peran (role), bukan orang. Artifact menjadi <code>ready</code> hanya setelah <strong>semua pemilik aktif</strong> mengonfirmasinya dengan <code>/deuz:ready</code>. Contohnya, <code>api-contract</code> baru <code>ready</code> setelah backend <strong>dan</strong> frontend sama-sama setuju.</p><p>Satu orang boleh memegang beberapa peran (mode solo): <code>/deuz:ready api-contract --as backend,frontend</code>. Di tim, setiap orang mengonfirmasi perannya sendiri. Work yang dimulai solo bisa diteruskan tim tanpa konversi.</p><p>Saat konfirmasi, deuz menyimpan <strong>hash</strong> isi dokumen. Kalau dokumen diubah setelah <code>ready</code>, statusnya kembali <code>draft</code> dan pemiliknya harus mengonfirmasi ulang. Dokumen yang bergantung padanya diberi tanda <em>recheck</em>.</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Arti</th></tr></thead><tbody><tr><td><code>missing</code></td><td>Belum ada filenya</td></tr><tr><td><code>draft</code></td><td>File ada, tapi belum dikonfirmasi semua pemilik</td></tr><tr><td><code>ready</code></td><td>Lengkap dan dikonfirmasi semua pemilik</td></tr><tr><td><code>skipped</code></td><td>Tidak diperlukan di work ini</td></tr></tbody></table><p>Artifact di-skip kalau tidak ada peran aktif yang memilikinya (misalnya tim tanpa designer), kalau proposal tidak mencentang areanya (tidak ada perubahan layar → <code>ui-design</code> di-skip), atau kalau proposal tidak mencantumkan capability dan belum ada delta (bug fix murni → <code>specs</code> di-skip).</p><h2 id="delta-menulis-yang-berubah-saja" tabindex="-1">Delta: menulis yang berubah saja <a class="header-anchor" href="#delta-menulis-yang-berubah-saja" aria-label="Permalink to &quot;Delta: menulis yang berubah saja&quot;">​</a></h2><p>Work tidak pernah mengedit spec permanen. Untuk setiap capability ia menulis <strong>delta</strong>:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## ADDED Requirements          ← perilaku baru</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## MODIFIED Requirements       ← perilaku yang berubah (salin blok lama utuh, lalu ubah)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## REMOVED Requirements        ← perilaku yang dihapus</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## RENAMED Requirements        ← nama requirement yang berganti</span></span></code></pre></div><p>Delta membuat reviewer langsung melihat apa yang berubah. Dua work juga bisa mengubah spec yang sama tanpa saling bertabrakan selama requirement-nya berbeda.</p><h2 id="archive" tabindex="-1">Archive <a class="header-anchor" href="#archive" aria-label="Permalink to &quot;Archive&quot;">​</a></h2><p>Saat semua artifact selesai dan semua task tercentang, <code>/deuz:archive</code> menggabungkan delta ke home <code>specs</code>, menjalankan promote (misalnya file desain ke home desain), lalu memindahkan work ke <code>work/archive/</code>. Proposal dan dokumen lain tetap tersimpan sebagai catatan &quot;kenapa fitur ini dibuat&quot;.</p><h2 id="gate-persetujuan-bisnis-opsional" tabindex="-1">Gate persetujuan bisnis (opsional) <a class="header-anchor" href="#gate-persetujuan-bisnis-opsional" aria-label="Permalink to &quot;Gate persetujuan bisnis (opsional)&quot;">​</a></h2><p>Kalau project mengaktifkan role <code>business</code>:</p><ul><li><strong>Gate 1:</strong> proposal yang mencentang area <code>business</code> harus disetujui bisnis. Sebuah <code>feature</code> selalu mencentangnya.</li><li><strong>Gate 2:</strong> kalau proposal juga mencentang <code>business-rules</code>, specs juga harus disetujui bisnis, khusus untuk aturan yang ditunjuk proposal.</li></ul><p>Stakeholder tidak menjalankan deuz. Analyst mencatat hasil rapat lalu mengonfirmasi atas nama mereka. Detailnya di <a href="./persetujuan-bisnis">Persetujuan bisnis</a>.</p><h2 id="dua-jalur" tabindex="-1">Dua jalur <a class="header-anchor" href="#dua-jalur" aria-label="Permalink to &quot;Dua jalur&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Jalur</th><th>Untuk</th><th>Bentuknya</th></tr></thead><tbody><tr><td><strong>Analyst</strong></td><td><code>feature</code>, atau <code>bug</code>/<code>enhancement</code> yang berdampak bisnis</td><td>Proposal lengkap, gate bisnis, specs, lalu seterusnya</td></tr><tr><td><strong>Engineer</strong></td><td><code>tech</code>, <code>chore</code>, atau <code>bug</code>/<code>enhancement</code> tanpa dampak bisnis</td><td>Proposal ringkas (sekitar 10 baris) dengan baris <code>Triage:</code>, biasanya tanpa specs, langsung ke tasks</td></tr></tbody></table><p>Satu template, satu alur. Ukuran dokumennya yang menyesuaikan dampak pekerjaan.</p>`,31)])])}const h=e(i,[["render",d]]);export{k as __pageData,h as default};
